-- BOOM.CASTLE(AU)[32+64]-V16.01
-- Do not edit this file. Any change breaks the decoder.
local _pklutw = 114
local _vqkqlp = 97
local _elcimb = 23
local _xzaqsr = ""

local _crfqjm = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"

local function _ujxkxr(a, b)
	local r, p = 0, 1
	for _ = 1, 8 do
		local x, y = a % 2, b % 2
		if x ~= y then r = r + p end
		a = (a - x) / 2; b = (b - y) / 2; p = p * 2
	end
	return r
end

local function _scmqip(d)
	d = d:gsub("[^" .. _crfqjm .. "=]", "")
	local o = {}
	local bits = (d:gsub("[%w%+/=]", function(c)
		if c == "=" then return "" end
		local f, s = (_crfqjm:find(c, 1, true) - 1), ""
		for i = 6, 1, -1 do
			s = s .. (f % 2 ^ i - f % 2 ^ (i - 1) > 0 and "1" or "0")
		end
		return s
	end))
	local n = 0
	for i = 1, #bits - 7, 8 do
		local c = 0
		for j = 0, 7 do
			if bits:sub(i + j, i + j) == "1" then c = c + 2 ^ (7 - j) end
		end
		n = n + 1
		o[n] = string.char(c)
	end
	return table.concat(o)
end

local _qtqfha = _scmqip(_xzaqsr)
local _klrwet = { _pklutw, _vqkqlp, _elcimb }
local _hgwijc = {}
for i = 1, #_qtqfha do
	_hgwijc[i] = string.char(_ujxkxr(_qtqfha:byte(i), _klrwet[(i - 1) % 3 + 1]))
end

local _gmbsiv = load or loadstring
local _nwrxsi, _avnodc = _gmbsiv(table.concat(_hgwijc), "=w")
if not _nwrxsi then
	gg.alert("Corrupted file: " .. tostring(_avnodc))
	os.exit()
end
_nwrxsi()
